function lpAgendaHtml(array $agenda): string
{
    $html='';
    foreach($agenda as $punt){if(!is_array($punt))continue;$onderwerp=trim((string)($punt['onderwerp']??''));if($onderwerp==='')continue;$html.='<div class="agenda-punt"><strong>'.lpEsc($onderwerp).'</strong>';$toel=trim((string)($punt['toelichting']??''));if($toel!=='')$html.='<br>'.nl2br(lpEsc($toel));$besluit=trim((string)($punt['besluit']??''));if($besluit!=='')$html.='<br><em>Besluit:</em> '.nl2br(lpEsc($besluit));$html.='</div>';}
    return $html;
}

